using UnityEngine;
using Verse;

namespace HermesVoice
{
    /// <summary>
    /// The balloon textures, loaded once at startup (never at draw time) from Textures/HermesVoice/Bubbles/.
    /// Every shape has three white-on-transparent layers that are tinted when drawn: fill, ink (outline, outside the
    /// body) and rim (thin band inside the edge, tinted with the speaker's colour). Generated by Mod/Textures/src/make_bubbles.py.
    /// </summary>
    [StaticConstructorOnStartup]
    public static class BubbleTex
    {
        const string Dir = "HermesVoice/Bubbles/";
        public static readonly Texture2D[] Fill = new Texture2D[5], Ink = new Texture2D[5], Rim = new Texture2D[5];
        public static readonly Texture2D TailFill, TailInk, TailRim, DotFill, DotInk, DotRim;

        static string ShapeName(BubbleKind k)
        {
            switch (k)
            {
                case BubbleKind.Shout: return "burst";
                case BubbleKind.Whisper: return "dashed";
                case BubbleKind.Thought: return "cloud";
                case BubbleKind.Narrator: return "caption";
                default: return "balloon";
            }
        }

        static BubbleTex()
        {
            for (int i = 0; i < 5; i++)
            {
                string n = ShapeName((BubbleKind)i);
                Fill[i] = Load(n + "_fill"); Ink[i] = Load(n + "_ink"); Rim[i] = Load(n + "_rim");
            }
            TailFill = Load("tail_fill"); TailInk = Load("tail_ink"); TailRim = Load("tail_rim");
            DotFill = Load("dot_fill"); DotInk = Load("dot_ink"); DotRim = Load("dot_rim");
        }

        static Texture2D Load(string name)
        {
            var t = ContentFinder<Texture2D>.Get(Dir + name, false);
            if (t == null) { Log.Warning("[HermesVoice] bubble texture missing: " + Dir + name); return BaseContent.ClearTex; }
            t.filterMode = FilterMode.Bilinear;
            t.wrapMode = TextureWrapMode.Clamp;
            return t;
        }
    }

    /// <summary>Immediate-mode drawing of one balloon layer. Allocation-free (Rect and Vector2 are structs).</summary>
    public static class BubbleDraw
    {
        /// <summary>
        /// 9-slice draw of an atlas (corner = BorderSrc source px, middle strip = midSrc). Corners are drawn at
        /// <paramref name="scale"/> UI px per source px. When <paramref name="tiled"/>, the edge strips repeat once per
        /// period instead of stretching (the layout has snapped the rect to whole periods).
        /// </summary>
        public static void NineSlice(Rect r, Texture2D tex, float scale, bool tiled, float midSrc)
        {
            float B = BubbleMetrics.BorderSrc, S = 2f * B + midSrc;
            float cs = B * scale;
            float midW = r.width - 2f * cs, midH = r.height - 2f * cs;
            float fb = B / S, fm = midSrc / S;
            // uv: x columns 0..2 -> start, width; v rows (from top) 0..2 (Unity v runs bottom-up)
            // corners
            Piece(tex, r.x, r.y, cs, cs, 0f, 1f - fb, fb, fb);
            Piece(tex, r.xMax - cs, r.y, cs, cs, 1f - fb, 1f - fb, fb, fb);
            Piece(tex, r.x, r.yMax - cs, cs, cs, 0f, 0f, fb, fb);
            Piece(tex, r.xMax - cs, r.yMax - cs, cs, cs, 1f - fb, 0f, fb, fb);
            if (midW > 0.01f)
            {
                if (tiled)
                {
                    int n = Mathf.Max(1, Mathf.RoundToInt(midW / (midSrc * scale)));
                    float tw = midW / n;
                    for (int i = 0; i < n; i++)
                    {
                        Piece(tex, r.x + cs + i * tw, r.y, tw, cs, fb, 1f - fb, fm, fb);
                        Piece(tex, r.x + cs + i * tw, r.yMax - cs, tw, cs, fb, 0f, fm, fb);
                    }
                }
                else
                {
                    Piece(tex, r.x + cs, r.y, midW, cs, fb, 1f - fb, fm, fb);
                    Piece(tex, r.x + cs, r.yMax - cs, midW, cs, fb, 0f, fm, fb);
                }
            }
            if (midH > 0.01f)
            {
                if (tiled)
                {
                    int n = Mathf.Max(1, Mathf.RoundToInt(midH / (midSrc * scale)));
                    float th = midH / n;
                    for (int i = 0; i < n; i++)
                    {
                        Piece(tex, r.x, r.y + cs + i * th, cs, th, 0f, fb, fb, fm);
                        Piece(tex, r.xMax - cs, r.y + cs + i * th, cs, th, 1f - fb, fb, fb, fm);
                    }
                }
                else
                {
                    Piece(tex, r.x, r.y + cs, cs, midH, 0f, fb, fb, fm);
                    Piece(tex, r.xMax - cs, r.y + cs, cs, midH, 1f - fb, fb, fb, fm);
                }
            }
            if (midW > 0.01f && midH > 0.01f) Piece(tex, r.x + cs, r.y + cs, midW, midH, fb, fb, fm, fm);
        }

        static void Piece(Texture2D tex, float x, float y, float w, float h, float u, float v, float uw, float vh)
        {
            GUI.DrawTextureWithTexCoords(new Rect(x, y, w, h), tex, new Rect(u, v, uw, vh));
        }

        /// <summary>
        /// One tail layer: the texture points straight down; it is rotated clockwise by tail.Angle around the anchor
        /// (GUIUtility.RotateAroundPivot works in the current GUI matrix's space, so it is correct at any UI scale),
        /// stretched to tail.Length, and the matrix is always restored.
        /// </summary>
        public static void Tail(Texture2D tex, TailInfo t)
        {
            float w = BubbleMetrics.TailW * BubbleMetrics.Unit;
            float stub = BubbleMetrics.TailStub;
            float h = (t.Length + stub) * (BubbleMetrics.TailH / BubbleMetrics.TailTipYSrc);
            var r = new Rect(t.AnchorX - w * 0.5f, t.AnchorY - stub, w, h);
            var prev = GUI.matrix;
            GUIUtility.RotateAroundPivot(t.Angle, new Vector2(t.AnchorX, t.AnchorY));
            GUI.DrawTexture(r, tex);
            GUI.matrix = prev;
        }

        /// <summary>A thought dot centred at (x, y) with the given fill diameter.</summary>
        public static void Dot(Texture2D tex, float x, float y, float fillDiameter)
        {
            float side = fillDiameter * BubbleMetrics.DotSize / (BubbleMetrics.DotSize - 2f * (BubbleMetrics.InkSrc + 3f));
            GUI.DrawTexture(new Rect(x - side * 0.5f, y - side * 0.5f, side, side), tex);
        }
    }
}
